/* Marketly API Reference viewer. Data: window.API_DATA (generated by docs/api/tools/build.mjs). */
(function () {
  'use strict';
  const D = window.API_DATA;
  const C = D.common;
  const MODS = new Map(D.modules.map((m) => [m.name, m]));
  const GROUPS = ['Platform', 'Participants', 'Catalog and stock', 'Buying', 'After-sales and money', 'Growth', 'Later phases'];
  const AREAS = Object.keys(C.areas);
  const PROTOTYPE = 'https://claude.ai/artifact/Ae7tfrsMsLrm8299EEATF1';
  const PRIMS = new Set(['string', 'text', 'int', 'number', 'bool', 'json', 'uuid', 'email', 'url', 'date', 'datetime']);
  const $ = (id) => document.getElementById(id);
  const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
  const store = { get(k, d) { try { return localStorage.getItem('mk-api-' + k) ?? d; } catch { return d; } }, set(k, v) { try { localStorage.setItem('mk-api-' + k, v); } catch { /* unavailable */ } } };

  let areaOn = new Set(JSON.parse(store.get('areas', JSON.stringify(AREAS))));
  const visibleArea = (a) => areaOn.has(a);
  const endpointsOf = (m) => m.endpoints.filter((e) => visibleArea(e.area));

  /* ------------------------------------------------ types */
  function typeRef(name, mod) {
    if (C.types[name]) return `<a href="#/conventions/types/${name}">${name}</a>`;
    if (name.includes('.')) { const [m, t] = name.split('.'); return `<a href="#/m/${m}/types/${t}">${esc(name)}</a>`; }
    if (mod && MODS.get(mod)?.types?.[name]) return `<a href="#/m/${mod}/types/${name}">${name}</a>`;
    return esc(name);
  }
  function typeExpr(expr, mod) {
    let t = String(expr).trim();
    let opt = '';
    if (t.endsWith('?')) { opt = '<span class="o">?</span>'; t = t.slice(0, -1); }
    let out;
    if (t.endsWith('[]')) out = `${typeExpr(t.slice(0, -2), mod)}[]`;
    else if (/^enum\(/.test(t)) out = `<span class="t">${t.slice(5, -1).split('|').map(esc).join(' | ')}</span>`;
    else if (/^map</.test(t)) out = `map&lt;${typeExpr(t.slice(4, -1), mod)}&gt;`;
    else if (/^Page</.test(t)) out = `Page&lt;${typeExpr(t.slice(5, -1), mod)}&gt;`;
    else if (PRIMS.has(t)) out = `<span class="t">${t}</span>`;
    else out = typeRef(t, mod);
    return out + opt;
  }
  /** Render any spec type value (string, {type,desc}, or inline object) as a readable tree. */
  function tree(v, mod, depth = 0) {
    if (v === null) return '<span class="d">no content</span>';
    if (v === undefined) return '';
    if (typeof v === 'string') return typeExpr(v, mod);
    if (typeof v.type === 'string') return `${typeExpr(v.type, mod)}${v.desc ? ` <span class="d">${esc(v.desc)}</span>` : ''}`;
    const rows = Object.entries(v).map(([k, x]) => `<div><span class="f">${esc(k)}</span>: ${tree(x, mod, depth + 1)}</div>`).join('');
    return `{<div class="ind">${rows}</div>}`;
  }
  const tyBlock = (v, mod, paging) => `<div class="ty">${paging ? `Page&lt;${tree(v, mod)}&gt; <span class="d">{ items, nextCursor, page?, totalPages?, total? }</span>` : tree(v, mod)}</div>`;

  /* ------------------------------------------------ mermaid (loaded on first use) */
  let mermaidPromise = null;
  function mermaidReady() {
    if (window.mermaid) return Promise.resolve(window.mermaid);
    mermaidPromise ??= new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/mermaid/11.6.0/mermaid.min.js';
      s.onload = () => resolve(window.mermaid);
      s.onerror = reject;
      document.head.appendChild(s);
    });
    return mermaidPromise;
  }
  const css = (n) => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
  let diagramSeq = 0;
  async function drawDiagrams() {
    const nodes = [...document.querySelectorAll('.diagram[data-src]')];
    if (!nodes.length) return;
    try {
      const mermaid = await mermaidReady();
      mermaid.initialize({
        startOnLoad: false, securityLevel: 'strict', theme: 'base',
        themeVariables: {
          fontFamily: css('--font-ui'), fontSize: '13px', background: css('--surface'),
          primaryColor: css('--brand-soft'), primaryTextColor: css('--text'), primaryBorderColor: css('--brand'),
          secondaryColor: css('--surface-2'), tertiaryColor: css('--surface-2'), lineColor: css('--text-3'),
          clusterBkg: css('--surface-2'), clusterBorder: css('--border-strong'), titleColor: css('--text-2'),
          edgeLabelBackground: css('--surface'), nodeTextColor: css('--text'),
        },
      });
      for (const n of nodes) {
        const { svg } = await mermaid.render(`mmd${++diagramSeq}`, n.dataset.src);
        n.innerHTML = svg;
        n.classList.remove('loading');
      }
    } catch {
      for (const n of nodes) { n.classList.remove('loading'); n.innerHTML = `<pre class="mono small">${esc(n.dataset.src)}</pre>`; }
    }
  }
  const diagram = (src) => `<div class="diagram loading" data-src="${esc(src)}">Drawing diagram…</div>`;

  /* ------------------------------------------------ pieces */
  const methodBadge = (m) => `<span class="method m-${m}">${m}</span>`;
  const screenLink = (id) => { const s = D.screens[id]; return `<a class="chip outline" href="${PROTOTYPE}#/${id}" target="_blank" rel="noopener" title="Open in the UI prototype">${esc(s ? s.title : id)}</a>`; };
  const modLink = (name) => `<a class="chip" href="#/m/${name}">${esc(name)}</a>`;
  const table = (head, rows) => `<div class="tbl-wrap"><table><thead><tr>${head.map((h) => `<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const pathHtml = (e) => { const pfx = e.fullPath.slice(0, e.fullPath.length - e.path.length); return `<span class="pfx">${esc(pfx)}</span>${esc(e.path)}`; };

  function endpoint(m, e, open) {
    const errs = { ...C.errors, ...(m.errorCodes ?? {}) };
    const flags = [
      e.auth !== 'staff' && e.auth !== 'seller' ? `<span class="chip">${e.auth}</span>` : '',
      e.permission ? `<span class="chip info" title="Permission">${esc(e.permission)}</span>` : '',
      e.idempotent ? '<span class="chip warn" title="Requires Idempotency-Key">idempotent</span>' : '',
      e.audited ? '<span class="chip" title="Recorded in the action history">audited</span>' : '',
      (e.phase ?? m.phase) > 1 ? `<span class="chip danger">phase ${e.phase ?? m.phase}</span>` : '',
    ].join('');
    const status = e.status ?? (e.response === null ? 204 : 200);
    const kv = [
      ['Operation', `<code>${m.name}.${esc(e.id)}</code>`],
      ['Auth', `${esc(C.auth[e.auth] ?? e.auth)}${e.permission ? ` · <code>${esc(e.permission)}</code>` : ''}`],
      e.approval && ['Approval', esc(e.approval)],
      e.idempotent && ['Idempotency', 'Send an <code>Idempotency-Key</code> header. A retry with the same key returns the first result.'],
      e.events?.length && ['Publishes', e.events.map((x) => `<code>${esc(x)}</code>`).join(', ')],
      e.screens?.length && ['Screens', `<span class="row">${e.screens.map(screenLink).join('')}</span>`],
    ].filter(Boolean).map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join('');
    const errCodes = [...new Set([...(e.errors ?? [])])];
    return `<details class="ep" id="ep-${esc(e.id)}"${open ? ' open' : ''}>
      <summary>${methodBadge(e.method)}<span class="ep-path">${pathHtml(e)}</span><span class="ep-flags">${flags}</span><span class="ep-sum">${esc(e.summary)}</span></summary>
      <div class="ep-body">
        ${e.desc ? `<p class="small">${esc(e.desc)}</p>` : ''}
        <dl class="kv">${kv}</dl>
        ${e.params ? `<div class="blk"><h4>Path parameters</h4>${tyBlock(e.params, m.name)}</div>` : ''}
        ${e.query || e.paging ? `<div class="blk"><h4>Query</h4>${tyBlock({ ...(e.query ?? {}), ...(e.paging ? { cursor: 'string?', page: 'int?', limit: 'int?' } : {}) }, m.name)}</div>` : ''}
        ${e.body !== undefined ? `<div class="blk"><h4>Request body</h4>${tyBlock(e.body, m.name)}</div>` : ''}
        <div class="blk"><h4>Response ${status}</h4>${e.response === undefined ? '<div class="ty"><span class="d">not specified</span></div>' : tyBlock(e.response, m.name, e.paging)}</div>
        ${errCodes.length ? `<div class="blk"><h4>Errors</h4>${table(['Code', 'Status', 'Meaning'], errCodes.map((c) => [`<code>${esc(c)}</code>`, errs[c]?.status ?? '', esc(errs[c]?.meaning ?? '')]))}</div>` : ''}
      </div>
    </details>`;
  }

  /* ------------------------------------------------ pages */
  function overview() {
    const eps = D.modules.flatMap((m) => m.endpoints);
    const byArea = Object.fromEntries(AREAS.map((a) => [a, eps.filter((e) => e.area === a).length]));
    const events = D.modules.reduce((n, m) => n + m.events.publishes.length, 0);
    const tables = D.modules.reduce((n, m) => n + (m.tables?.length ?? 0), 0);
    const perms = D.modules.reduce((n, m) => n + (m.permissions?.length ?? 0), 0);
    // Dependency layers: a module sits one layer right of its deepest required dependency.
    const level = {};
    const lv = (n) => (level[n] ??= 1 + Math.max(-1, ...(MODS.get(n)?.dependsOn ?? []).filter((d) => MODS.has(d)).map(lv)));
    D.modules.forEach((m) => lv(m.name));
    const layers = [];
    for (const m of D.modules) (layers[level[m.name]] ??= []).push(m);
    return `<div class="v-col">
      <div class="sec"><span class="eyebrow">Phase 2 · Backend design</span><h1 class="title">Marketly API design</h1>
        <p class="lead">${esc(C.info.description)}</p></div>
      <div class="stats">
        <div class="stat"><b>${D.modules.length}</b><span>Modules</span></div>
        <div class="stat"><b>${eps.length}</b><span>Endpoints</span></div>
        <div class="stat"><b>${tables}</b><span>Tables</span></div>
        <div class="stat"><b>${events}</b><span>Events</span></div>
        <div class="stat"><b>${perms}</b><span>Permissions</span></div>
      </div>
      <div class="sec"><h2>API areas</h2><div class="grid">${AREAS.map((a) => `<div class="card"><h3>${esc(C.areas[a].title)}</h3><p><code>${esc(C.areas[a].prefix)}</code></p><p class="small muted">${esc(C.areas[a].audience)}</p><p class="small">${esc(C.areas[a].auth)}</p><p class="small"><b>${byArea[a]}</b> endpoints</p></div>`).join('')}</div></div>
      <div class="sec"><h2>Stack</h2>${table(['Concern', 'Choice', 'Why'], (C.stack ?? []).map((s) => [esc(s.concern), `<b>${esc(s.choice)}</b>`, esc(s.why)]))}</div>
      <div class="sec"><h2>Module rules</h2><ul class="plain">${(C.moduleRules ?? []).map((r) => `<li>${esc(r)}</li>`).join('')}</ul></div>
      ${GROUPS.map((g) => { const ms = D.modules.filter((m) => m.group === g); return ms.length ? `<div class="sec"><h2>${g}<span class="count">${ms.length}</span></h2><div class="grid">${ms.map((m) => `<a class="card" href="#/m/${m.name}" style="color:inherit;text-decoration:none"><div class="row" style="justify-content:space-between"><h3>${esc(m.title)}</h3>${m.phase > 1 ? `<span class="chip danger">phase ${m.phase}</span>` : ''}</div><p class="small muted">${esc(m.summary)}</p><p class="small" style="margin-top:8px"><b>${m.endpoints.length}</b> endpoints · ${(m.tables ?? []).length} tables${(m.dependsOn ?? []).length ? ` · needs ${m.dependsOn.join(', ')}` : ''}</p></a>`).join('')}</div></div>` : ''; }).join('')}
      <div class="sec"><h2>Dependency layers</h2><p class="small muted">Each module needs only modules in layers to its left, so the system starts left to right and any module can be removed once nothing to its right needs it. Optional dependencies are not counted. Each module page shows its own dependency graph.</p>
        <div class="layers">${layers.map((ms, i) => `<div class="layer"><span class="eyebrow">Layer ${i}${i === 0 ? ' · needs nothing' : ''}</span>${ms.sort((a, b) => a.name.localeCompare(b.name)).map((m) => `<a class="chip${m.phase > 2 ? ' danger' : ''}" href="#/m/${m.name}" title="${esc((m.dependsOn ?? []).length ? 'Needs ' + m.dependsOn.join(', ') : 'Needs nothing')}">${esc(m.name)}</a>`).join('')}</div>`).join('')}</div></div>
      <div class="sec"><h2>Launch scenarios (plan ch. 21)</h2>${table(['#', 'Scenario', 'Modules in order'], (C.scenarios ?? []).map((s) => [s.n, esc(s.name), `<span class="row">${s.flow.map(modLink).join('<span class="muted">→</span>')}</span>`]))}</div>
    </div>`;
  }

  function conventions(anchor) {
    return `<div class="v-col">
      <div class="sec"><span class="eyebrow">Conventions</span><h1 class="title">How every endpoint behaves</h1></div>
      <div class="sec"><h2>Areas and sign-in</h2>${table(['Area', 'Prefix', 'Who', 'Auth'], AREAS.map((a) => [esc(C.areas[a].title), `<code>${esc(C.areas[a].prefix)}</code>`, esc(C.areas[a].audience), esc(C.areas[a].auth)]))}
        ${table(['auth value', 'Meaning'], Object.entries(C.auth).map(([k, v]) => [`<code>${k}</code>`, esc(v)]))}</div>
      <div class="sec"><h2>Pagination</h2><p class="small">Every list pages two ways. The Android app scrolls with <code>?cursor=</code>; the website shows numbered pages with <code>?page=</code>. Both use <code>limit</code>.</p>
        ${tyBlock(C.pagination.query, null)}<div class="ty">{ items: T[], nextCursor: string | null, page?: int, totalPages?: int, total?: int }</div></div>
      <div class="sec"><h2>Errors</h2><p class="small">Every error has the same body: <code>{ "error": { "code", "message", "details" } }</code>. Modules add their own codes; see each module's Access tab.</p>${table(['Code', 'Status', 'Meaning'], Object.entries(C.errors).map(([c, d]) => [`<code>${c}</code>`, d.status, esc(d.meaning)]))}</div>
      <div class="sec"><h2>Headers</h2>${table(['Header', 'Use'], Object.entries(C.headers).map(([h, d]) => [`<code>${h}</code>`, esc(d)]))}</div>
      <div class="sec" id="types"><h2>Shared types</h2>${Object.entries(C.types).map(([n, t]) => `<div class="card" id="type-${n}"><h3><code>${n}</code></h3>${tyBlock(t, null)}</div>`).join('')}</div>
    </div>`;
  }

  /** Focused graph: what this module needs (solid), may use (dashed), and who needs it. */
  function depGraph(m) {
    const id = (n) => n.replace(/-/g, '_');
    const lines = ['flowchart LR', `  ${id(m.name)}["${m.name}"]:::me`];
    for (const d of m.requiredBy) lines.push(`  ${id(d)}["${d}"] --> ${id(m.name)}`);
    for (const d of m.dependsOn ?? []) lines.push(`  ${id(m.name)} --> ${id(d)}["${d}"]`);
    for (const d of m.optionalDeps ?? []) lines.push(`  ${id(m.name)} -.-> ${id(d)}["${d}"]`);
    lines.push(`  classDef me fill:${css('--brand')},color:${css('--on-brand')},stroke:${css('--brand')}`);
    return lines.join('\n');
  }

  const TABS = [['endpoints', 'Endpoints'], ['graphql', 'GraphQL'], ['types', 'Types'], ['data', 'Data'], ['flows', 'Status flows'], ['events', 'Events'], ['access', 'Access and jobs']];
  function modulePage(m, tab, anchor) {
    const gqlFields = G ? Object.entries(G.fieldOwner).filter(([, mod]) => mod === m.name).length : 0;
    const counts = { graphql: gqlFields, endpoints: endpointsOf(m).length, types: Object.keys(m.types ?? {}).length, data: (m.tables ?? []).length, flows: (m.stateMachines ?? []).length, events: m.events.publishes.length + m.events.consumes.length, access: (m.permissions ?? []).length };
    const head = `<div class="sec"><span class="eyebrow">${esc(m.group)} · launch phase ${m.phase}${m.chapters?.length ? ` · plan ch. ${m.chapters.join(', ')}` : ''}</span>
      <h1 class="title">${esc(m.title)} <code class="muted" style="font-size:16px">${m.name}</code></h1>
      <p class="lead">${esc(m.summary)}</p>
      <div class="row small">${(m.dependsOn ?? []).length ? `<span class="muted">Needs</span>${m.dependsOn.map(modLink).join('')}` : '<span class="muted">No required dependencies</span>'}${(m.optionalDeps ?? []).length ? `<span class="muted">· Optional</span>${m.optionalDeps.map(modLink).join('')}` : ''}${m.requiredBy.length ? `<span class="muted">· Needed by</span>${m.requiredBy.map(modLink).join('')}` : ''}</div></div>
      <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))"><div class="card"><h3>Owns</h3><ul class="plain small">${m.owns.map((o) => `<li>${esc(o)}</li>`).join('')}</ul></div>${m.notOwns?.length ? `<div class="card"><h3>Not here</h3><ul class="plain small">${m.notOwns.map((o) => `<li>${esc(o)}</li>`).join('')}</ul></div>` : ''}</div>
      ${(m.dependsOn ?? []).length + m.requiredBy.length + (m.optionalDeps ?? []).length ? diagram(depGraph(m)) : ''}
      <nav class="tabs" aria-label="Module sections">${TABS.map(([k, l]) => `<a href="#/m/${m.name}/${k}" class="${tab === k ? 'on' : ''}"${tab === k ? ' aria-current="page"' : ''}>${l}<span class="count">${counts[k]}</span></a>`).join('')}</nav>`;
    let body = '';
    if (tab === 'endpoints') {
      body = AREAS.map((a) => {
        const eps = m.endpoints.filter((e) => e.area === a && visibleArea(a));
        return eps.length ? `<div class="sec"><div class="area-head"><h3>${esc(C.areas[a].title)}</h3><code>${esc(C.areas[a].prefix.replace('{module}', m.name))}</code></div><div class="eps">${eps.map((e) => endpoint(m, e, anchor === e.id)).join('')}</div></div>` : '';
      }).join('') || '<p class="empty">No endpoints in the selected API areas.</p>';
    } else if (tab === 'graphql') {
      const src = G?.fragments?.[m.name];
      const ext = G ? Object.entries(G.fieldOwner).filter(([k, mod]) => mod === m.name && !(G.areas.admin.types.find((t) => t.name === k.split('.')[0])?.owner === m.name)).map(([k]) => k) : [];
      body = src ? `<p class="small muted">This module's GraphQL fragment. It defines the module's own types, its <code>Query</code> fields, and fields it adds to other modules' types (resolved by this module). See <a href="#/graphql/store">GraphQL</a> for the composed schemas and screen queries.</p>
        ${ext.length ? `<div class="sec"><h2>Fields this module adds to other types</h2><div class="row">${ext.map((k) => `<code class="chip outline">${esc(k)}</code>`).join('')}</div></div>` : ''}
        ${codeBlock(src)}` : '<p class="empty">This module has no GraphQL fragment: its data is only needed through REST.</p>';
    } else if (tab === 'types') {
      body = Object.entries(m.types ?? {}).map(([n, t]) => `<div class="card" id="type-${n}"><h3><code>${n}</code></h3>${tyBlock(t, m.name)}</div>`).join('') || '<p class="empty">No types.</p>';
      if (m.publicApi?.length) body += `<div class="sec"><h2>In-process API for other modules</h2>${table(['Function', 'Signature', 'Used by'], m.publicApi.map((f) => [`<code>${esc(f.name)}</code><div class="small muted">${esc(f.desc ?? '')}</div>`, `<code>${esc(f.signature)}</code>`, (f.usedBy ?? []).map(modLink).join(' ')]))}</div>`;
    } else if (tab === 'data') {
      body = `<p class="small muted">PostgreSQL schema <code>${m.name.replace(/-/g, '_')}</code>. Other modules are referenced by id only.</p>` + ((m.tables ?? []).map((t) => `<div class="sec"><h2 style="font-size:16px"><code>${esc(t.name)}</code></h2>${t.desc ? `<p class="small muted">${esc(t.desc)}</p>` : ''}${table(['Column', 'Type'], Object.entries(t.columns).map(([c, v]) => [`<code>${esc(c)}</code>`, `<code>${esc(v)}</code>`]))}${t.indexes?.length ? `<p class="small">Indexes: ${t.indexes.map((i) => `<code>${esc(i)}</code>`).join(', ')}</p>` : ''}</div>`).join('') || '<p class="empty">No tables.</p>');
    } else if (tab === 'flows') {
      body = (m.stateMachines ?? []).map((sm) => `<div class="sec flow"><h2 style="font-size:16px">${esc(sm.name)} <code class="muted">${esc(sm.field)}</code></h2>
        ${diagram(['stateDiagram-v2', `  [*] --> ${sm.initial}`, ...sm.transitions.map(([a, ev, b]) => `  ${a} --> ${b}: ${ev}`)].join('\n'))}
        ${table(['From', 'Action', 'To'], sm.transitions.map(([a, ev, b]) => [`<code>${esc(a)}</code>`, esc(ev), `<code>${esc(b)}</code>`]))}
        ${sm.notes ? `<p class="small">${esc(sm.notes)}</p>` : ''}</div>`).join('') || '<p class="empty">No status flows.</p>';
    } else if (tab === 'events') {
      body = `<div class="sec"><h2>Publishes</h2>${m.events.publishes.length ? table(['Event', 'When', 'Payload', 'Consumed by'], m.events.publishes.map((e) => [`<code>${esc(e.name)}</code>`, esc(e.when), e.payload ? tyBlock(e.payload, m.name) : '', e.consumedBy.map(modLink).join(' ') || '<span class="muted">-</span>'])) : '<p class="empty">None.</p>'}</div>
        <div class="sec"><h2>Consumes</h2>${m.events.consumes.length ? table(['Event', 'From', 'Does'], m.events.consumes.map((e) => [`<code>${esc(e.name)}</code>`, e.from ? modLink(e.from) : '<span class="chip danger">no publisher</span>', esc(e.does)])) : '<p class="empty">None.</p>'}</div>`;
    } else {
      body = [
        `<div class="sec"><h2>Permissions</h2>${(m.permissions ?? []).length ? table(['Key', 'Who', 'Allows'], m.permissions.map((p) => [`<code>${esc(p.key)}</code>`, p.audience, esc(p.desc)])) : '<p class="empty">None.</p>'}</div>`,
        m.approvalActions?.length ? `<div class="sec"><h2>Approval actions</h2><p class="small muted">Checked through the access module: limits per role, second reviewer, nobody approves their own request.</p>${table(['Action', 'Limit', 'Second reviewer', 'Approvers', 'Meaning'], m.approvalActions.map((a) => [`<code>${esc(a.key)}</code>`, esc(a.limit), esc(a.secondReviewer), esc(a.approvers ?? ''), esc(a.desc)]))}</div>` : '',
        m.errorCodes && Object.keys(m.errorCodes).length ?`<div class="sec"><h2>Module error codes</h2>${table(['Code', 'Status', 'Meaning'], Object.entries(m.errorCodes).map(([c, d]) => [`<code>${esc(c)}</code>`, d.status, esc(d.meaning)]))}</div>` : '',
        m.jobs?.length ? `<div class="sec"><h2>Background jobs</h2>${table(['Job', 'Schedule', 'Does'], m.jobs.map((j) => [`<code>${esc(j.name)}</code>`, esc(j.schedule), esc(j.does)]))}</div>` : '',
        m.settings?.length ? `<div class="sec"><h2>Settings</h2>${table(['Key', 'Default', 'Meaning'], m.settings.map((s) => [`<code>${esc(s.key)}</code>`, `<code>${esc(JSON.stringify(s.default))}</code>`, esc(s.desc)]))}</div>` : '',
        m.integrations?.length ? `<div class="sec"><h2>Integrations</h2><ul class="plain small">${m.integrations.map((i) => `<li><b>${esc(i.name)}</b>: ${esc(i.purpose)}</li>`).join('')}</ul></div>` : '',
        m.notes?.length ? `<div class="sec"><h2>Notes</h2><ul class="plain small">${m.notes.map((n) => `<li>${esc(n)}</li>`).join('')}</ul></div>` : '',
      ].join('');
    }
    return `<div class="v-col">${head}${body}</div>`;
  }

  /* ------------------------------------------------ GraphQL */
  const G = window.API_GQL || null;
  const GQL_AREAS = ['store', 'seller', 'admin'];
  function sdlHtml(src) {
    return esc(src)
      .replace(/(&quot;&quot;&quot;[\s\S]*?&quot;&quot;&quot;|&quot;[^&\n]*?&quot;)/g, '<span class="g-str">$1</span>')
      .replace(/(^|\n)(\s*#[^\n]*)/g, '$1<span class="g-com">$2</span>')
      .replace(/\b(type|extend|enum|input|interface|implements|union|scalar|query|fragment|on)\b/g, '<span class="g-kw">$1</span>')
      .replace(/(@\w+)/g, '<span class="g-dir">$1</span>');
  }
  const codeBlock = (src) => `<pre class="code">${sdlHtml(src)}</pre>`;
  const gqlTypeLink = (area, t) => {
    const base = String(t).replace(/[[\]!]/g, '');
    const known = G?.areas[area]?.types.some((x) => x.name === base && x.fields?.length);
    return known ? String(t).replace(base, `<a href="#/graphql/${area}/type/${base}">${base}</a>`) : esc(t);
  };

  function graphqlPage(area, kind, name) {
    if (!G) return '<div class="v-col"><p class="empty">GraphQL design data is not built yet. Run node docs/api/tools/graphql.mjs.</p></div>';
    area = GQL_AREAS.includes(area) ? area : 'store';
    const A = G.areas[area];
    const ops = G.operations.filter((o) => o.area === area);
    const tabs = `<nav class="tabs" aria-label="GraphQL schema">${GQL_AREAS.map((a) => `<a href="#/graphql/${a}" class="${a === area ? 'on' : ''}">${esc(C.areas[a].title.replace(' API', ''))} schema<span class="count">${G.operations.filter((o) => o.area === a).length} queries</span></a>`).join('')}</nav>`;
    let body;
    if (kind === 'type') {
      const t = A.types.find((x) => x.name === name);
      body = t ? `<div class="sec"><span class="eyebrow">${esc(t.kind)}${t.owner ? ` · owned by ${t.owner}` : ''}</span><h2 style="font-size:24px"><code>${esc(t.name)}</code></h2>${t.desc ? `<p class="small">${esc(t.desc)}</p>` : ''}
        ${t.fields.length ? table(['Field', 'Type', 'From module', 'About'], t.fields.map((f) => { const mod = G.fieldOwner[`${t.name}.${f.name}`] || t.owner; return [`<code>${esc(f.name)}${f.args.length ? `(${esc(f.args.join(', '))})` : ''}</code>`, `<code>${gqlTypeLink(area, f.type)}</code>`, mod ? `<a class="chip${mod !== t.owner ? ' brand' : ''}" href="#/m/${mod}/graphql">${esc(mod)}</a>` : '', esc(f.desc ?? '')]; })) : ''}
        ${t.values ? `<p class="row">${t.values.map((v) => `<span class="chip">${esc(v)}</span>`).join('')}</p>` : ''}</div>` : '<p class="empty">Type not in this schema.</p>';
    } else if (kind === 'op') {
      const o = ops.find((x) => x.name === name);
      body = o ? `<div class="sec"><span class="eyebrow">Persisted query · ${area}</span><h2 style="font-size:24px">${esc(o.name)}</h2>
        <dl class="kv"><dt>Screens</dt><dd><span class="row">${o.screens.map(screenLink).join('')}</span></dd>${o.replaces ? `<dt>Replaces</dt><dd>${esc(o.replaces)}</dd>` : ''}${o.why ? `<dt>Why GraphQL</dt><dd>${esc(o.why)}</dd>` : ''}<dt>Depth</dt><dd>${o.depth}</dd><dt>Persisted id</dt><dd><code>${o.id.slice(0, 16)}…</code></dd></dl>
        ${codeBlock(o.text)}</div>` : '<p class="empty">Query not found.</p>';
    } else {
      body = `<div class="sec"><h2>Screen queries<span class="count">${ops.length}</span></h2>${ops.length ? `<div class="eps">${ops.map((o) => `<a class="hit" href="#/graphql/${area}/op/${o.name}"><span class="k">query</span><span><span class="mono">${esc(o.name)}</span><br><span class="small muted">${esc(o.screens.map((s) => D.screens[s]?.title ?? s).join(' · '))}${o.replaces ? ` · replaces ${esc(o.replaces)}` : ''}</span></span></a>`).join('')}</div>` : '<p class="empty">No screen queries yet.</p>'}</div>
        <div class="sec"><h2>Query fields<span class="count">${A.queries.length}</span></h2>${table(['Field', 'Returns', 'Module', 'About'], A.queries.map((q) => [`<code>${esc(q.name)}${q.args.length ? `(${esc(q.args.join(', '))})` : ''}</code>`, `<code>${gqlTypeLink(area, q.type)}</code>`, q.module ? `<a class="chip" href="#/m/${q.module}/graphql">${esc(q.module)}</a>` : '', esc(q.desc ?? '')]))}</div>
        <div class="sec"><h2>Types<span class="count">${A.types.filter((t) => t.fields.length).length}</span></h2><div class="row">${A.types.filter((t) => t.fields.length && t.name !== 'Query').sort((a, b) => a.name.localeCompare(b.name)).map((t) => `<a class="chip" href="#/graphql/${area}/type/${t.name}">${esc(t.name)}</a>`).join('')}</div></div>`;
    }
    return `<div class="v-col">
      <div class="sec"><span class="eyebrow">Read layer</span><h1 class="title">GraphQL</h1>
        <p class="lead">GraphQL serves screens whose data spans several modules, in one round trip. Every write stays on REST. Each module contributes the types and fields it owns; removing a module removes its fields.</p>
        <div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))">
          <div class="card"><h3>Use GraphQL</h3><p class="small muted">Product page, order detail, dashboards, 360° admin views: anything combining several modules.</p></div>
          <div class="card"><h3>Use REST</h3><p class="small muted">Every write (idempotency, approvals, audit), uploads, webhooks, ad serving, exports.</p></div>
          <div class="card"><h3>Persisted queries</h3><p class="small muted">Apps send a registered query id in production. Max depth 9, cost limits, batched resolvers.</p></div>
        </div></div>
      ${tabs}${body}</div>`;
  }

  /* ------------------------------------------------ coverage (audit) */
  const AU = window.API_AUDIT || null;
  const ROUTE_INDEX = new Map(D.modules.flatMap((m) => m.endpoints.map((e) => [`${e.method} ${e.fullPath.replace(/\{\w+\}/g, '{}')}`, { m: m.name, id: e.id }])));
  function refLink(ref) {
    const r = String(ref).trim();
    if (r.startsWith('gql ')) {
      const x = r.slice(4).trim();
      if (x.includes(':')) { const [area, tf] = x.split(':'); const [type] = tf.split('.'); return `<a class="chip info" href="#/graphql/${area}/type/${type}">${esc(x)}</a>`; }
      const [area, name] = x.split('/');
      return `<a class="chip info" href="#/graphql/${area}/op/${name}">${esc(x)}</a>`;
    }
    const mm = r.match(/^(GET|POST|PUT|PATCH|DELETE)\s+(\S+)/);
    const hit = mm && ROUTE_INDEX.get(`${mm[1]} ${mm[2].replace(/\{\w+\}/g, '{}')}`);
    return hit ? `<a class="chip outline" href="#/m/${hit.m}/endpoints/${hit.id}"><b class="method m-${mm[1]}" style="padding:0 4px">${mm[1]}</b>&nbsp;${esc(mm[2])}</a>` : `<span class="chip danger">${esc(r)}</span>`;
  }
  const STATUS_CHIP = { covered: 'brand', missing: 'danger', 'client-only': '', later: 'warn', 'non-api': '', 'not-in-plan': 'info' };
  const statusChip = (s) => `<span class="chip ${STATUS_CHIP[s] ?? ''}">${esc(s)}</span>`;

  function coveragePage(kind, key) {
    if (!AU) return '<div class="v-col"><p class="empty">Coverage audit not built yet. Run node docs/api/tools/audit.mjs.</p></div>';
    const screenFiles = Object.entries(AU.files).filter(([f]) => f.startsWith('screens-'));
    const screenEntries = screenFiles.flatMap(([, list]) => list);
    const plan = AU.files.plan ?? [];
    const count = (list, s) => list.filter((e) => e.status === s).length;
    const summary = (list) => ['covered', 'missing', 'later', 'not-in-plan', 'client-only', 'non-api'].map((s) => count(list, s) ? `${statusChip(s)} <b>${count(list, s)}</b>` : '').filter(Boolean).join(' ');
    const tabs = `<nav class="tabs" aria-label="Coverage"><a href="#/coverage/screens" class="${kind !== 'plan' ? 'on' : ''}">UI prototype screens<span class="count">${screenEntries.length}</span></a><a href="#/coverage/plan" class="${kind === 'plan' ? 'on' : ''}">Plan requirements<span class="count">${plan.length}</span></a></nav>`;
    let body;
    if (kind === 'plan') {
      const chapters = [...new Set(plan.map((e) => e.chapter))].sort((a, b) => a - b);
      body = chapters.map((ch) => { const list = plan.filter((e) => e.chapter === ch); return `<details class="ep"${key === String(ch) ? ' open' : ''}><summary><span class="method m-GET">ch. ${ch}</span><span class="ep-path">${list.length} requirements</span><span class="ep-flags">${summary(list)}</span></summary><div class="ep-body">${table(['Requirement', 'Status', 'Served by', 'Note'], list.map((e) => [esc(e.requirement), statusChip(e.status), `<span class="row">${(e.api ?? []).map(refLink).join('')}</span>`, esc(e.note ?? '')]))}</div></details>`; }).join('');
      body = `<div class="eps">${body}</div>`;
    } else {
      const byScreen = new Map();
      for (const e of screenEntries) (byScreen.get(e.screen) ?? byScreen.set(e.screen, []).get(e.screen)).push(e);
      const order = Object.keys(D.screens);
      const ids = [...byScreen.keys()].sort((a, b) => order.indexOf(a) - order.indexOf(b));
      body = `<div class="eps">${ids.map((id) => { const list = byScreen.get(id); return `<details class="ep" id="ep-${esc(id)}"${key === id ? ' open' : ''}><summary><span class="method m-POST">${esc(id.split('/')[0])}</span><span class="ep-path">${esc(D.screens[id]?.title ?? id)} <span class="muted">${esc(id)}</span></span><span class="ep-flags">${summary(list)}</span></summary><div class="ep-body"><p class="small"><a href="${PROTOTYPE}#/${id}" target="_blank" rel="noopener">Open this screen in the UI prototype</a></p>${table(['Element', 'State', 'Kind', 'Status', 'Served by'], list.map((e) => [esc(e.element), esc(e.state ?? 'all'), esc(e.kind), statusChip(e.status), `<span class="row">${(e.api ?? []).map(refLink).join('')}</span>${e.note ? `<div class="small muted">${esc(e.note)}</div>` : ''}`]))}</div></details>`; }).join('')}</div>`;
    }
    return `<div class="v-col">
      <div class="sec"><span class="eyebrow">Audit · ${esc(AU.generatedAt)}</span><h1 class="title">Coverage</h1>
        <p class="lead">Every action and data block on every UI prototype screen, and every requirement in the plan document, mapped to the REST endpoint or GraphQL query that serves it. Each reference is checked to exist.</p>
        <div class="stats">
          <div class="stat"><b>${screenEntries.length}</b><span>Screen elements checked</span></div>
          <div class="stat"><b>${count(screenEntries, 'covered')}</b><span>Served by the API</span></div>
          <div class="stat"><b>${plan.length}</b><span>Plan requirements checked</span></div>
          <div class="stat"><b>${count(plan, 'covered')}</b><span>Served by the API</span></div>
          <div class="stat"><b>${count(screenEntries, 'missing') + count(plan, 'missing')}</b><span>Still missing</span></div>
        </div></div>
      ${tabs}${body}</div>`;
  }

  /* ------------------------------------------------ search */
  const INDEX = [];
  for (const m of D.modules) {
    for (const e of m.endpoints) INDEX.push({ kind: e.method, area: e.area, href: `#/m/${m.name}/endpoints/${e.id}`, title: e.fullPath, sub: `${e.summary}${e.permission ? ` · ${e.permission}` : ''}`, hay: `${e.method} ${e.fullPath} ${e.summary} ${e.desc ?? ''} ${e.permission ?? ''} ${(e.screens ?? []).join(' ')} ${m.name}.${e.id}`.toLowerCase() });
    for (const t of Object.keys(m.types ?? {})) INDEX.push({ kind: 'type', href: `#/m/${m.name}/types/${t}`, title: `${m.name}.${t}`, sub: Object.keys(m.types[t]).slice(0, 8).join(', '), hay: `${m.name}.${t} ${t}`.toLowerCase() });
    for (const e of m.events.publishes) INDEX.push({ kind: 'event', href: `#/m/${m.name}/events`, title: e.name, sub: e.when, hay: `${e.name} ${e.when}`.toLowerCase() });
    for (const p of m.permissions ?? []) INDEX.push({ kind: 'perm', href: `#/m/${m.name}/access`, title: p.key, sub: p.desc, hay: `${p.key} ${p.desc}`.toLowerCase() });
    for (const t of m.tables ?? []) INDEX.push({ kind: 'table', href: `#/m/${m.name}/data`, title: `${m.name.replace(/-/g, '_')}.${t.name}`, sub: t.desc ?? '', hay: `${m.name} ${t.name} ${Object.keys(t.columns).join(' ')}`.toLowerCase() });
  }
  function searchPage(q) {
    const terms = q.toLowerCase().split(/\s+/).filter(Boolean);
    const hits = INDEX.filter((h) => (!h.area || visibleArea(h.area)) && terms.every((t) => h.hay.includes(t))).slice(0, 200);
    return `<div class="v-col"><div class="sec"><span class="eyebrow">Search</span><h1 class="title" style="font-size:26px">${hits.length} result${hits.length === 1 ? '' : 's'} for “${esc(q)}”</h1></div>
      ${hits.length ? `<div class="eps">${hits.map((h) => `<a class="hit" href="${h.href}">${/^[A-Z]+$/.test(h.kind) ? methodBadge(h.kind) : `<span class="k">${h.kind}</span>`}<span><span class="mono">${esc(h.title)}</span><br><span class="small muted">${esc(h.sub)}</span></span></a>`).join('')}</div>` : '<p class="empty">Nothing matches. Try a path segment (payouts), a permission (finance.), an event (orders.order) or a screen id (seller/order).</p>'}</div>`;
  }

  /* ------------------------------------------------ chrome + router */
  function nav(active) {
    const link = (href, label, on, extra = '') => `<a href="${href}" class="${on ? 'on' : ''}"${on ? ' aria-current="page"' : ''}>${label}${extra}</a>`;
    $('vNav').innerHTML = link('#/overview', 'Overview', active === 'overview') + link('#/conventions', 'Conventions', active === 'conventions') + link('#/graphql/store', 'GraphQL', active === 'graphql', G ? `<span class="n">${G.operations.length}</span>` : '') + link('#/coverage/screens', 'Coverage', active === 'coverage') +
      GROUPS.map((g) => { const ms = D.modules.filter((m) => m.group === g); return ms.length ? `<h3>${g}</h3>${ms.map((m) => link(`#/m/${m.name}`, esc(m.title), active === m.name, `${m.phase > 1 ? `<span class="ph">P${m.phase}</span>` : ''}<span class="n">${endpointsOf(m).length}</span>`)).join('')}` : ''; }).join('');
  }
  function chrome() {
    $('vStats').textContent = `${D.modules.length} modules · ${D.modules.reduce((n, m) => n + m.endpoints.length, 0)} endpoints`;
    $('vAreas').innerHTML = AREAS.map((a) => `<button type="button" data-area="${a}" aria-pressed="${areaOn.has(a)}">${esc(C.areas[a].title.replace(' API', ''))}</button>`).join('');
  }

  function route() {
    const h = decodeURIComponent(location.hash.replace(/^#\/?/, '')) || 'overview';
    const parts = h.split('/');
    let html; let active;
    if (parts[0] === 'm' && MODS.has(parts[1])) {
      const tab = TABS.some(([k]) => k === parts[2]) ? parts[2] : 'endpoints';
      html = modulePage(MODS.get(parts[1]), tab, parts[3]);
      active = parts[1];
      document.title = `${MODS.get(parts[1]).title} · Marketly API Reference`;
    } else if (parts[0] === 'coverage') {
      html = coveragePage(parts[1], parts.slice(2).join('/')); active = 'coverage'; document.title = 'Coverage · Marketly API Reference';
    } else if (parts[0] === 'graphql') {
      html = graphqlPage(parts[1], parts[2], parts[3]); active = 'graphql'; document.title = 'GraphQL · Marketly API Reference';
    } else if (parts[0] === 'conventions') {
      html = conventions(parts[2]); active = 'conventions'; document.title = 'Conventions · Marketly API Reference';
    } else if (parts[0] === 'search') {
      html = searchPage(parts.slice(1).join('/')); active = ''; document.title = 'Search · Marketly API Reference';
    } else {
      html = overview(); active = 'overview'; document.title = 'Marketly API Reference';
    }
    nav(active);
    $('vMain').innerHTML = html;
    $('vNav').classList.remove('open');
    $('vMenu').setAttribute('aria-expanded', 'false');
    // Scroll to a type / endpoint anchor, else to top
    const anchor = parts[0] === 'm' ? parts[3] : parts[0] === 'conventions' ? parts[2] : null;
    const target = anchor && (document.getElementById(`type-${anchor}`) || document.getElementById(`ep-${anchor}`));
    if (target) target.scrollIntoView({ block: 'start' }); else $('vMain').scrollTop = 0;
    drawDiagrams();
  }

  document.addEventListener('click', (e) => {
    const area = e.target.closest('[data-area]');
    if (area) {
      const a = area.dataset.area;
      if (areaOn.has(a) && areaOn.size > 1) areaOn.delete(a); else areaOn.add(a);
      store.set('areas', JSON.stringify([...areaOn]));
      chrome(); route();
      return;
    }
    if (e.target.closest('#vTheme')) {
      const dark = document.documentElement.getAttribute('data-theme') ? document.documentElement.getAttribute('data-theme') === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
      document.documentElement.setAttribute('data-theme', dark ? 'light' : 'dark');
      route();
      return;
    }
    if (e.target.closest('#vMenu')) {
      const open = !$('vNav').classList.contains('open');
      $('vNav').classList.toggle('open', open);
      $('vMenu').setAttribute('aria-expanded', String(open));
    }
  });
  $('vSearchForm').addEventListener('submit', (e) => { e.preventDefault(); const q = $('vSearch').value.trim(); location.hash = q ? `#/search/${encodeURIComponent(q)}` : '#/overview'; });
  let t;
  $('vSearch').addEventListener('input', (e) => { clearTimeout(t); t = setTimeout(() => { const q = e.target.value.trim(); if (q.length >= 2) location.hash = `#/search/${encodeURIComponent(q)}`; }, 250); });
  window.addEventListener('hashchange', route);
  chrome();
  route();
})();
